//! Bounded, cluster-aware lines for terminal Markdown. Inputs to emit are
//! sanitized text; emitStyled accepts only lines generated by this renderer.
const std = @import("std");
const text = @import("text.zig");
const theme = @import("theme.zig");
const Allocator = std.mem.Allocator;

pub const Tone = enum { normal, heading, strong, code, quote, link, muted, user };
pub const Style = struct { tone: Tone = .normal, bold: bool = false, italic: bool = false, strike: bool = false, underline: bool = false };

/// Shared across the main writer and every table cell. Limits apply to work
/// and all generated storage, before viewport selection or repeated URLs can
/// amplify a small source. A plain fallback receives a fresh bounded budget.
pub const Budget = struct {
    bytes: usize = 0,
    lines: usize = 0,
    work: usize = 0,
    max_bytes: usize = 4 * 1024 * 1024,
    max_lines: usize = 256 * 1024 + 64,
    max_work: usize = 1024 * 1024,

    pub fn step(self: *Budget, n: usize) !void {
        if (n > self.max_work - self.work) return error.MarkdownRenderLimit;
        self.work += n;
    }

    fn append(self: *Budget, n: usize) !void {
        if (n > self.max_bytes - self.bytes) return error.MarkdownRenderLimit;
        self.bytes += n;
    }

    fn finish(self: *Budget) !void {
        if (self.lines == self.max_lines) return error.MarkdownRenderLimit;
        self.lines += 1;
    }
};

pub const Writer = struct {
    a: Allocator,
    columns: usize,
    ansi: bool,
    base: Tone = .normal,
    style: Style = .{},
    prefix: []const u8 = "",
    continuation: ?[]const u8 = null,
    lines: std.ArrayList([]const u8) = .empty,
    line: std.ArrayList(u8) = .empty,
    col: usize = 0,
    budget: ?*Budget = null,

    fn append(self: *Writer, s: []const u8) !void {
        if (self.budget) |budget| try budget.append(s.len);
        try self.line.appendSlice(self.a, s);
    }

    fn byte(self: *Writer, value: u8) !void {
        if (self.budget) |budget| try budget.append(1);
        try self.line.append(self.a, value);
    }

    pub fn sgr(self: *Writer) !void {
        if (!self.ansi) return;
        try self.append(theme.reset);
        const tone = if (self.style.tone == .normal) self.base else self.style.tone;
        try self.append(switch (tone) {
            .normal => "",
            .heading => theme.heading,
            .strong => theme.strong,
            .code => theme.code,
            .quote => theme.quote,
            .link => theme.link,
            .muted => theme.muted,
            .user => theme.user,
        });
        if (self.style.bold) try self.append("\x1b[1m");
        if (self.style.italic) try self.append("\x1b[3m");
        if (self.style.strike) try self.append("\x1b[9m");
        if (self.style.underline) try self.append("\x1b[4m");
    }

    pub fn setStyle(self: *Writer, style: Style) !void {
        self.style = style;
        if (self.col != 0) try self.sgr();
    }

    fn start(self: *Writer) !void {
        if (self.col != 0) return;
        try self.sgr();
        var i: usize = 0;
        // A deep quote/list prefix must leave room for at least one glyph.
        while (i < self.prefix.len) {
            const c = text.nextCluster(self.prefix, i, self.col);
            if (self.col + c.width >= self.columns) break;
            try self.append(self.prefix[i..c.end]);
            self.col += c.width;
            i = c.end;
        }
        if (self.continuation) |prefix| {
            self.prefix = prefix;
            self.continuation = null;
        }
    }

    pub fn finish(self: *Writer) !void {
        if (self.budget) |budget| try budget.finish();
        if (self.ansi) {
            if (self.base == .user or self.style.tone == .code) {
                if (self.col == 0) try self.start();
                // The entire row belongs to the user card/code block, including
                // blank lines; resets never bleed into subsequent UI rows.
                for (self.col..self.columns) |_| try self.byte(' ');
            }
            try self.append(theme.reset);
        }
        try self.lines.append(self.a, try self.line.toOwnedSlice(self.a));
        self.col = 0;
    }

    pub fn boundary(self: *Writer) !void {
        if (self.col != 0) try self.finish();
    }

    pub fn emit(self: *Writer, s: []const u8) !void {
        if (self.budget) |budget| try budget.step(s.len);
        var i: usize = 0;
        while (i < s.len) {
            if (s[i] == '\n') {
                try self.finish();
                i += 1;
                continue;
            }
            try self.start();
            var c = text.nextCluster(s, i, self.col);
            if (self.col > 0 and c.width > self.columns - self.col) {
                try self.finish();
                try self.start();
                c = text.nextCluster(s, i, self.col);
            }
            if (self.col == 0 and c.width == 0) {
                try self.append("◌");
                self.col = 1;
            }
            if (c.width > self.columns - self.col) {
                try self.byte('?');
                self.col += 1;
            } else if (s[i] == '\t') {
                for (0..c.width) |_| try self.byte(' ');
                self.col += c.width;
            } else {
                try self.append(s[i..c.end]);
                self.col += c.width;
            }
            i = c.end;
        }
    }

    /// Only an internally rendered cell/line, never raw provider/user bytes.
    pub fn emitStyled(self: *Writer, s: []const u8) !void {
        if (self.budget) |budget| try budget.step(s.len);
        try self.start();
        const width = displayWidth(s);
        if (width > self.columns - self.col) return error.MarkdownCellOverflow;
        try self.append(s);
        self.col += width;
        try self.sgr();
    }
};

/// Width of renderer-owned SGR lines; no terminal movement sequences accepted.
pub fn displayWidth(s: []const u8) usize {
    var i: usize = 0;
    var width: usize = 0;
    while (i < s.len) {
        if (s[i] == 0x1b and i + 1 < s.len and s[i + 1] == '[') {
            i += 2;
            while (i < s.len and (std.ascii.isDigit(s[i]) or s[i] == ';')) : (i += 1) {}
            if (i < s.len and s[i] == 'm') i += 1;
        } else {
            const c = text.nextCluster(s, i, width);
            width += c.width;
            i = c.end;
        }
    }
    return width;
}

test "writer caps work bytes and generated lines before allocation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var work: Budget = .{ .max_work = 3 };
    var w: Writer = .{ .a = arena.allocator(), .columns = 10, .ansi = false, .budget = &work };
    try std.testing.expectError(error.MarkdownRenderLimit, w.emit("long"));
    try std.testing.expectEqual(@as(usize, 0), w.line.items.len);
    var bytes: Budget = .{ .max_bytes = 3 };
    w = .{ .a = arena.allocator(), .columns = 10, .ansi = false, .budget = &bytes };
    try std.testing.expectError(error.MarkdownRenderLimit, w.emit("long"));
    try std.testing.expectEqual(@as(usize, 3), w.line.items.len);
    var lines: Budget = .{ .max_lines = 1 };
    w = .{ .a = arena.allocator(), .columns = 1, .ansi = false, .budget = &lines };
    try std.testing.expectError(error.MarkdownRenderLimit, w.emit("abc"));
    try std.testing.expectEqual(@as(usize, 1), w.lines.items.len);
}

test "colored rows preserve width, card background and ANSI ownership" {
    try text.initLocale();
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    var w: Writer = .{ .a = arena.allocator(), .columns = 10, .ansi = true, .base = .user };
    try w.emit("中文 é\nnext");
    try w.finish();
    for (w.lines.items) |line| {
        try std.testing.expectEqual(@as(usize, 10), displayWidth(line));
        try std.testing.expect(std.mem.indexOf(u8, line, theme.user_background) != null);
        try std.testing.expect(std.mem.endsWith(u8, line, theme.reset));
    }
}
